use super::{V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решения 339. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static DEX_FAIL: &[SettingDef] = &[
    d("DEX", "dex.pool_fail_pause_ms", K::Integer, L::Positive, "мс", V, "Решение 339: ошибка чтения ОДНОГО пула (откат контракта, например DODO «KJUDGE_ERROR», ответ не по ABI, сбой узла на этом пуле, ошибка eth_blockNumber при реорге) касается только этого пула — для всех видов пулов и всех путей (перечитывание по событию, пары многомонетного пула, пары общего контракта WooFi, пулы «каждым блоком», Balancer V2, LB V2.1, очередь повтора): пул недостоверен (в котировки и сделки не идёт), причина — на экране «Монеты» и в журнале (одна запись на начало неудач и на смену причины), остальные пулы пачки работают без переподключения подписки и без перечитывания. Повтор — не раньше этой паузы; с каждой неудачей подряд пауза удваивается до dex.pool_fail_pause_max_ms; пул на паузе по своим событиям не читается (позиция события отмечается, повтор прочитает не раньше неё). Пул НЕ бросается (ревью t153): после dex.pool_load_retries попыток — одна запись журнала, а повтор идёт дальше с паузой, пока пул не прочитается (кроме пула, ждущего незаданную настройку, — он вернётся, когда её зададут); событие недостоверного пула не на паузе ставит его на перечитку. Так рабочий пул после сбоя узла возвращается сам, без переподключения. Ошибка связи или лимита узла (нет связи, 5xx, таймаут, 429) ошибкой пула не считается: пауза не растёт (после восстановления узла пул читается через эту паузу, а не через потолок), журнал — одна запись на сбой узла; смена причины в журнале — по коду ошибки, не по тексту. Обрыв WebSocket, пропуск логов лентой, лог без позиции, смена источника событий — по-прежнему переподключение. Не задана — как раньше: прочая ошибка (кроме StaleData) рвёт сессию пачки и перечитывает все её пулы. Необязательна").dex_venue().optional(),
    d("DEX", "dex.pool_fail_pause_max_ms", K::Integer, L::Positive, "мс", V, "Решение 339: потолок растущей паузы повтора пула после неудач чтения (dex.pool_fail_pause_ms удваивается с каждой неудачей подряд, но не больше этого). Действует только при заданной dex.pool_fail_pause_ms. Не задана — пауза не растёт (всегда dex.pool_fail_pause_ms). Необязательна").dex_venue().optional(),
    d("DEX", "dex.pool_unread_alert_s", K::Integer, L::Positive, "секунды", V, "Ревью t153 (решение 339): пул не читается дольше стольких секунд подряд (от первой неудачи чтения; при заданной dex.pool_fail_pause_ms) — одно уведомление dex.pool_unread в Telegram и запись журнала dex.pool: вид, монета, сколько не читается, неудач подряд, последняя причина. Повтора нет до удачного чтения пула (новый эпизод — новое уведомление). Проверка — на каждой неудаче чтения пула, поэтому пул на паузе уведомляется на первой неудаче после порога. Включение события — экран «Уведомления». Не задана — уведомления нет. Необязательна").dex_venue().optional(),
    d("DEX", "dex.per_block_skip_same", K::Bool, L::None, "да/нет", V, "Задача t160: пулы, которые бот перечитывает на КАЖДОМ блоке (WooFi, Lista, Infinity Stable, Nomiswap Stable, Metric, iZiSwap / Biswap V3, KyberSwap DMM, SmarDex, Curve NG, Balancer V2, LB V2.1), не шлют ядру событие, если состояние пула после чтения не изменилось (поколение состояния то же) — ядро не пересчитывает направления зря. Первое чтение пула и возврат из недостоверного шлются всегда. Реестр (блок чтения, свежесть для проверок) обновляется как раньше. Действует только при dex.pool_events_keep = да: без неё событие пула при полном канале ядра теряется, и повтор каждым блоком — единственная доставка. Пары WooFi по логу контракта и перечитывание по событиям пула — как раньше. Не задана / нет — как раньше: событие на каждое чтение. Необязательна").dex_venue().optional(),
];
